item.content:encoded:
.popup.hero-popup li a {
	padding: 20px 28px;
	border-radius: 12px;
	font-size: 16px;
}

.popup.header-popup li a {
	padding: 16px 20px;
	border-radius: 12px;
	background-color: #00A79D;
	color: white;
	font-size: 13px;
}

@media (max-width:500px) {
	ul.popup  {
		display: inline-flex !important;
		flex-direction: column !important;
		align-items: center !important;
		gap: 12px !important;
		width: 100% !important;
	}

	.popup li {
		display: inline-flex;
		width: 100% !important;
		justify-content: center;
		margin: 0 !important;
	}
}

/* old */


.popup li{
	display:inline-flex;

}

.popup li:last-child{
	margin-left:20px;
}

.popup.card-btn li:last-child{
	align-self: start !important;
	margin-left:0;
}

ul.popup.header-popup.card-btn {
    margin: 0 !important;
    justify-self: center;
}


.popup li a{
  background-color: #FFFFFF;
  font-family: "Poppins", Sans-serif;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  fill: #58A190;
  color: #58A190;
  border-style: solid;
  border-width: 2px 2px 2px 2px;
  border-color: #58A190;
  border-radius: 50px 50px 50px 50px;
  padding: 12px 15px 10px 15px;
	transition:.5s;
}

.popup li a:hover, .form-btn input[type="submit"]:hoverz{
  background-image: linear-gradient(284deg, #F8EC27 0%, #0583D3 100%);
  color: #fff !important;
  text-decoration: none;
}

ul.popup.hero-popup li a {
	min-width: 310px;
	padding: 16px 28px;
}



/* new */
.popup.hero-popup li a {
	padding: 20px 28px;
	border-radius: 12px;
	font-size: 16px;
}

.popup.header-popup li a, .form-btn input[type="submit"] {
	padding: 16px 20px;
	border-radius: 12px;
	background-color: #00A79D;
	color: white;
	font-size: 13px;
}

.form-btn input[type="submit"] {
/* 	border-radius: 4px; */
	padding: 20px;
	font-size: 14px;
	text-transform: uppercase;
}

ul.card-popup {
	display: flex;
	justify-content: center;
	width: 100%;
	margin: 0 !important;
	padding: 0 !important;	
}

@media (max-width:500px) {
	ul.popup  {
		display: inline-flex !important;
		flex-direction: column !important;
		align-items: center !important;
		gap: 12px !important;
		width: 100% !important;
		margin: 0;
	}

	.popup li {
		display: inline-flex;
		width: 100% !important;
		justify-content: center;
		margin: 0 !important;
	}

	.popup li a {
		padding: 12px !important;
		text-transform: inherit;
	}

/* mobile responsive image box */
	.image-box-container .elementor-image-box-wrapper {
		display: flex;
		gap: 20px;
		align-items: center;
/* 		flex-direction: row ; */
	}
}

/* END */



/* popup box - boxzilla */
.boxzilla  {
	padding: 60px 20px 10px 20px;
	border-radius: 4px;
}


/* product card css */
.eael-elements-flip-box-padding {
    padding: 0px 16px 5px 16px;
}


/* Scroll To TOP CSS */
@media (max-width: 600px) {
	.ast-scroll-to-top-right {
    bottom: 50px;
}
}

