a:1:{s:10:"custom_css";s:4980:"/* Container for floating icons */
.floating-icons-container {
    position: relative;
    width: 100%;
    height: 100vh;
    overflow: hidden;
    pointer-events: none;
}

/* Base floating icon styles */
.floating-icon {
    position: absolute;
    font-size: 24px;
    color: rgba(76, 175, 80, 0.6);
    pointer-events: auto;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    z-index: 10;
    animation: floatAnimation 6s ease-in-out infinite;
}

/* Individual icon positioning and delays */
.floating-icon:nth-child(1) {
    top: 15%;
    left: 10%;
    animation-delay: 0s;
    font-size: 28px;
}

.floating-icon:nth-child(2) {
    top: 25%;
    right: 15%;
    animation-delay: 2s;
    font-size: 20px;
}

.floating-icon:nth-child(3) {
    top: 45%;
    left: 5%;
    animation-delay: 4s;
    font-size: 32px;
}

.floating-icon:nth-child(4) {
    top: 60%;
    right: 8%;
    animation-delay: 1s;
    font-size: 24px;
}

.floating-icon:nth-child(5) {
    top: 75%;
    left: 20%;
    animation-delay: 3s;
    font-size: 26px;
}

.floating-icon:nth-child(6) {
    top: 35%;
    right: 25%;
    animation-delay: 5s;
    font-size: 22px;
}

/* Floating animation keyframes */
@keyframes floatAnimation {
    0%, 100% {
        transform: translateY(0px) rotate(0deg) scale(1);
        opacity: 0.6;
    }
    25% {
        transform: translateY(-15px) rotate(5deg) scale(1.05);
        opacity: 0.8;
    }
    50% {
        transform: translateY(-8px) rotate(-3deg) scale(0.95);
        opacity: 1;
    }
    75% {
        transform: translateY(-20px) rotate(8deg) scale(1.1);
        opacity: 0.7;
    }
}

/* Hover effects */
.floating-icon:hover {
    transform: scale(1.5) rotate(360deg) !important;
    color: #4CAF50;
    opacity: 1 !important;
    animation-play-state: paused;
    cursor: pointer;
    filter: drop-shadow(0 5px 15px rgba(76, 175, 80, 0.4));
}

/* Different hover effects for variety */
.floating-icon:nth-child(odd):hover {
    transform: scale(1.8) rotate(-360deg) !important;
}

.floating-icon:nth-child(even):hover {
    transform: scale(1.6) rotate(180deg) translateY(-10px) !important;
}

/* Pulse effect for some icons */
.floating-icon.pulse {
    animation: floatAnimation 6s ease-in-out infinite, pulseEffect 3s ease-in-out infinite;
}

@keyframes pulseEffect {
    0%, 100% {
        box-shadow: 0 0 0 0 rgba(76, 175, 80, 0.4);
    }
    50% {
        box-shadow: 0 0 0 15px rgba(76, 175, 80, 0);
    }
}

/* Spinning leaves animation */
.floating-icon.spin {
    animation: floatAnimation 6s ease-in-out infinite, spinLeaf 8s linear infinite;
}

@keyframes spinLeaf {
    0% {
        transform: rotate(0deg);
    }
    100% {
        transform: rotate(360deg);
    }
}

/* Breathing effect */
.floating-icon.breathe {
    animation: floatAnimation 6s ease-in-out infinite, breatheEffect 4s ease-in-out infinite;
}

@keyframes breatheEffect {
    0%, 100% {
        transform: scale(1);
    }
    50% {
        transform: scale(1.2);
    }
}

/* Mobile responsive adjustments */
@media (max-width: 768px) {
    .floating-icon {
        font-size: 18px;
    }
    
    .floating-icon:nth-child(1) { font-size: 20px; }
    .floating-icon:nth-child(3) { font-size: 24px; }
    
    /* Reduce some icons on mobile */
    .floating-icon:nth-child(5),
    .floating-icon:nth-child(6) {
        display: none;
    }
    
    /* Adjust positions for mobile */
    .floating-icon:nth-child(1) {
        top: 20%;
        left: 5%;
    }
    
    .floating-icon:nth-child(2) {
        top: 30%;
        right: 5%;
    }
}

/* Advanced effects */
.floating-icon.glow {
    animation: floatAnimation 6s ease-in-out infinite, glowEffect 2s ease-in-out infinite alternate;
}

@keyframes glowEffect {
    from {
        text-shadow: 0 0 5px rgba(76, 175, 80, 0.5);
    }
    to {
        text-shadow: 0 0 20px rgba(76, 175, 80, 0.8), 0 0 30px rgba(76, 175, 80, 0.6);
    }
}

/* Particle trail effect */
.floating-icon.trail::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 4px;
    height: 4px;
    background: rgba(76, 175, 80, 0.4);
    border-radius: 50%;
    transform: translate(-50%, -50%);
    animation: trailEffect 2s linear infinite;
}

@keyframes trailEffect {
    0% {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
    100% {
        opacity: 0;
        transform: translate(-50%, -50%) scale(3);
    }
}

/* Wind effect - icons sway */
.floating-icon.wind {
    animation: floatAnimation 6s ease-in-out infinite, windSway 4s ease-in-out infinite;
}

@keyframes windSway {
    0%, 100% {
        transform: translateX(0px);
    }
    25% {
        transform: translateX(10px);
    }
    75% {
        transform: translateX(-8px);
    }
}";}

