<thead>
<tr>
<th>Nutrient Component</th>
<th>Percentage</th>
<th>Description</th>
</tr>
</thead>
<tbody>
<tr class="primary">
<td>
<div class="nutrient-name"><b>Ammonium Lignosulphonate</b></div></td>
<td class="percentage"><b>6.3%</b></td>
<td class="description"><span style="font-weight: 400;">A natural chelating agent that binds with essential nutrients, keeping them in a plant-available form for improved uptake and efficiency.</span><span style="font-weight: 400;">
</span></td>
</tr>
<tr class="primary">
<td>
<div class="nutrient-name"><b>Zinc </b></div>
<div class="nutrient-name">(Zn)</div></td>
<td class="percentage"><b> 0.20%</b><b>
</b></td>
<td class="description"><span style="font-weight: 400;">Vital for enzyme activation, chlorophyll production, and healthy leaf development, especially during early growth stages.</span><span style="font-weight: 400;">
</span></td>
</tr>
<tr class="primary">
<td>
<div class="nutrient-name"><strong>Iron</strong></div>
<div class="nutrient-name">(Fe)</div></td>
<td class="percentage"><b>0.18%</b><b>
</b></td>
<td class="description"><span style="font-weight: 400;">Essential for chlorophyll synthesis and overall plant vigour, preventing yellowing (chlorosis) in leaves.</span></td>
</tr>
<tr class="secondary">
<td>
<div class="nutrient-name"><b>Manganese</b></div>
<div class="nutrient-name">(Mn)</div></td>
<td class="percentage"><b>0.18%</b></td>
<td class="description"><span style="font-weight: 400;">Supports photosynthesis and helps activate enzymes involved in nitrogen metabolism.</span><span style="font-weight: 400;">
</span></td>
</tr>
<tr class="specialty">
<td>
<div class="chemical-formula"><b>Boron </b></div>
<div class="chemical-formula">(B)<b>
</b></div></td>
<td class="percentage"><b> 0.08%</b></td>
<td class="description"><span style="font-weight: 400;">Critical for cell wall formation, root tip health, and reproductive growth, including flowering and fruit set.</span><span style="font-weight: 400;">
</span></td>
</tr>
<tr class="micronutrient">
<td><b>Ascophyllum Nodosum </b>(Kelp Extract)</td>
<td class="percentage"><b> 0.90%</b><b>
</b></td>
<td class="description"><span style="font-weight: 400;"> Marine plant extract that stimulates root growth, enhances stress tolerance, and supports overall plant resilience.</span></td>
</tr>
</tbody>
</table>","_margin":{"unit":"px","top":"20","right":"0","bottom":"-24","left":"0","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out"},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"7bc886a","elType":"container","settings":{"flex_direction":"column","flex_gap":{"column":"40","row":"40","isLinked":true,"unit":"px","size":40},"padding":{"unit":"px","top":"60","right":"20","bottom":"60","left":"20","isLinked":false},"__globals__":{"background_color":""},"background_color":"#F1F4B217","element_pack_agbg_color_list":[{"_id":"ed56016"},{"start_color":"#567445","end_color":"#1D1BE0","_id":"fd8b194"}],"_element_id":"coverage"},"elements":[{"id":"350ee9f","elType":"widget","settings":{"title":"Coverage","align":"center","typography_typography":"custom","typography_font_family":"Poppins","typography_font_size":{"unit":"px","size":32,"sizes":[]},"typography_font_weight":"700","_element_custom_width":{"unit":"%","size":60,"sizes":[]},"_background_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_gradient_angle_tablet":{"unit":"deg","size":"","sizes":[]},"_background_gradient_angle_mobile":{"unit":"deg","size":"","sizes":[]},"_background_hover_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_hover_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_hover_color_b_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_hover_color_b_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_hover_gradient_angle_tablet":{"unit":"deg","size":"","sizes":[]},"_background_hover_gradient_angle_mobile":{"unit":"deg","size":"","sizes":[]},"__globals__":{"title_color":"globals/colors?id=e7f9