a:2:{s:10:"custom_css";s:1761:"table {
    width: 100%;
    /*border-collapse: collapse;*/
    /*border: 1px solid #98B63C;*/
    }

th {
    background: #f1f5f9;
    color: #2A83C5;
    font-weight: 600;
    padding: 1rem;
    text-align: left;
    border-bottom: 2px solid #e2e8f0;
    text-align: center;
}

/*th:last-child {*/
/*    text-align: center;*/
/*}*/

tbody tr {
    border-bottom: 1px solid #f1f5f9;
    transition: background-color 0.2s ease;
}

tbody tr:hover {
    background: #f8fafc;
}

tbody tr:last-child {
    border-bottom: none;
}

td {
    padding: 0.875rem 1rem;
    color: #98b63c;
    vertical-align: center;
    text-align: center;
}

.nutrient-name {
    font-weight: 500;
    color: #98b63c;
}

.chemical-formula {
    font-size: 0.875rem;
    color: #c;
    margin-top: 2px;
}

.percentage {
    font-weight: 600;
    color: #2a83c5;
    font-size: 1rem;
}

.description {
    font-size: 0.875rem;
    line-height: 1.4;
}

/* Simple category indicators */
/*.primary { border-left: 3px solid #059669; }*/
/*.secondary { border-left: 3px solid #7c3aed; }*/
/*.micronutrient { border-left: 3px solid #dc2626; }*/
/*.specialty { border-left: 3px solid #ea580c; }*/

@media (max-width: 768px) {

    .container {
        border-radius: 8px;
    }

    .header {
        padding: 1.5rem;
    }

    .title {
        font-size: 1.5rem;
    }

    th, td {
        padding: 0.75rem;
        font-size: 0.9rem;
    }

    .description {
        font-size: 0.8rem;
    }
}


#ast-scroll-top {
color: #fff;
background-color: #2A83C5;
}

.desktop-only {
display: inline;
}

/* Hide break on mobile */
@media (max-width: 768px) {
.desktop-only {
display: none;
}
}";s:20:"ep_grid_line_columns";s:0:"";}

