t_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out"},"elements":[],"widgetType":"heading"},{"id":"2095011","elType":"widget","settings":{"editor":"<table><thead><tr><th>Nutrient Component</th><th>Percentage</th><th>Description</th></tr></thead><tbody><tr><td><div><b>Total Nitrogen</b></div><div>(N)</div></td><td class="percentage">4%</td><td><span style="font-weight: 400;">Fuels vigorous leaf and stem growth by boosting chlorophyll production and protein synthesis, resulting in lush, green foliage.</span><span style="font-weight: 400;"><br /></span></td></tr><tr><td><div><b>Available Phosphoric Acid</b></div><div>(P₂O₅)</div></td><td class="percentage">3%</td><td><span style="font-weight: 400;"> Promotes strong root systems and efficient energy transfer, supporting flowering, fruiting, and early establishment.</span></td></tr><tr><td><div><b>Soluble Potash</b></div><div>(K₂O)</div></td><td class="percentage">6%</td><td><span style="font-weight: 400;"> Enhances plant vigor, stress resistance, and water regulation while improving crop size, quality, and flavour.</span></td></tr><tr><td><div><b>Sulphur</b></div><div>(S)</div></td><td class="percentage">10%</td><td><span style="font-weight: 400;"> Supports protein and enzyme production, improves nitrogen efficiency, and deepens leaf colour.</span><span style="font-weight: 400;"><br /></span></td></tr><tr><td><div><b>Manganese</b></div><div>(Mn-EDTA)</div></td><td class="percentage"><b>0.09%</b><b><br /></b></td><td><span style="font-weight: 400;"> It aids photosynthesis, nitrogen metabolism, and root growth while increasing stress tolerance.</span></td></tr><tr><td><div><b>Zinc</b></div><div>((Zn-EDTA)</div></td><td class="percentage">0.12%</td><td><span style="font-weight: 400;">Essential for growth hormones, leaf formation, and flower and fruit set.<br /></span></td></tr><tr><td><div><b>Copper</b></div><div>(Mn-EDTA)</div></td><td class="percentage">0.09%</td><td><span style="font-weight: 400;">Strengthens cell walls, supports reproductive growth, and improves disease resistance.</span><span style="font-weight: 400;"><br /></span></td></tr><tr><td><div><b>Boron</b></div><div>(B)</div></td><td class="percentage">0.03%</td><td><span style="font-weight: 400;"> Vital for flowering, pollen development, nutrient transport, and cell wall formation.</span><span style="font-weight: 400;"><br /></span></td></tr><tr><td><div><b>Molybdenum</b></div><div>(Mo-EDTA)</div><div> </div></td><td class="percentage">0.01%</td><td><span style="font-weight: 400;">Improves nitrogen use efficiency and supports protein synthesis for healthy growth.</span></td></tr></tbody></table>","_margin":{"unit":"px","top":"20","right":"0","bottom":"-24","left":"0","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out"},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"7bc886a","elType":"container","settings":{"flex_direction":"column","flex_gap":{"column":"40","row":"40","isLinked":true,"unit":"px","size":40},"padding":{"unit":"px","top":"60","right":"20","bottom":"60","left":"20","isLinked":false},"__globals__":{"background_color":""},"background_color":"#F1F4B217","element_pack_agbg_color_list":[{"_id":"ed56016"},{"start_color":"#567445","end_color":"#1D1BE0","_id":"fd8b194"}],"_element_id":"coverage"},"elements":[{"id":"350ee9f","elType":"widget","settings":{"title":"Coverage","align":"center","typography_typography":"custom","typography_font_family":"Poppins","typography_font_size":{"unit":"px","size":32,"sizes":[]},"typography_font_weight":"700","_element_custom_width":{"unit":"%","size":60,"sizes":[]},"_background_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_mobile":{