<thead>
<tr>
<th>Nutrient Component</th>
<th>Concentration</th>
<th>Description</th>
</tr>
</thead>
<tbody>
<tr>
<td>
<div><b>Glomus aggregatum</b></div></td>
<td class="percentage">5,500 viable propagules per gram (0.36 US oz)</td>
<td>Promotes vigorous root branching and enhances the uptake of phosphorus, zinc, and copper, thereby aiding early plant establishment.</td>
</tr>
<tr>
<td>
<div><b>Glomus etunicatum</b></div></td>
<td class="percentage">5,500 viable propagules per gram (0.36 US oz)</td>
<td>Enhances drought tolerance and improves nutrient access in sandy or low-fertility soils.</td>
</tr>
<tr>
<td>
<div><b>Glomus geosporum</b></div></td>
<td class="percentage">5,500 viable propagules per gram (0.36 US oz)</td>
<td>Supports growth in cooler or wetter soils, improving plant resilience under stress.</td>
</tr>
<tr>
<td>
<div><b>Glomus intraradices</b></div></td>
<td class="percentage">5,500 viable propagules per gram (0.36 US oz)</td>
<td>Rapidly colonizes roots, increasing the efficiency of nutrient and water absorption.</td>
</tr>
<tr>
<td>
<div><b>Glomus mosseae</b></div></td>
<td class="percentage">2,000 viable propagules per gram (0.36 US oz)</td>
<td>Provides strong, long-lasting colonization and improved resistance to soil-borne diseases.</td>
</tr>
</tbody>
</table>","_margin":{"unit":"px","top":"20","right":"0","bottom":"-24","left":"0","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out"},"elements":[],"widgetType":"text-editor"},{"id":"846c078","elType":"widget","settings":{"title":"Note: Viable propagules include spores, hyphae fragments, and colonized root pieces capable of forming mycorrhizal associations with plant roots.","align":"center","typography_typography":"custom","typography_font_family":"Poppins","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"400","_element_width":"initial","_element_width_mobile":"inherit","_element_custom_width":{"unit":"%","size":60,"sizes":[]},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out","__globals__":{"title_color":"globals/colors?id=987f53f"}},"elements":[],"widgetType":"heading"}],"isInner":false},{"id":"7bc886a","elType":"container","settings":{"flex_direction":"column","flex_gap":{"column":"40","row":"40","isLinked":true,"unit":"px","size":40},"padding":{"unit":"px","top":"60","right":"20","bottom":"60","left":"20","isLinked":false},"__globals__":{"background_color":""},"background_color":"#F1F4B217","element_pack_agbg_color_list":[{"_id":"ed56016"},{"start_color":"#567445","end_color":"#1D1BE0","_id":"fd8b194"}],"_element_id":"coverage"},"elements":[{"id":"350ee9f","elType":"widget","settings":{"title":"Coverage","align":"center","typography_typography":"custom","typography_font_family":"Poppins","typography_font_size":{"unit":"px","size":32,"sizes":[]},"typography_font_weight":"700","_element_custom_width":{"unit":"%","size":60,"sizes":[]},"_background_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_color_b_s