x","size":120,"sizes":[]},"image_size_tablet":{"unit":"px","size":"","sizes":[]},"image_size_mobile":{"unit":"px","size":"","sizes":[]},"title_typography_typography":"custom","title_typography_font_family":"Poppins","title_typography_font_size":{"unit":"px","size":20,"sizes":[]},"title_typography_font_weight":"600","_padding":{"unit":"rem","top":"2","right":"1","bottom":"2","left":"1","isLinked":false},"_padding_tablet":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"_padding_mobile":{"unit":"rem","top":"","right":"","bottom":"","left":"","isLinked":true},"_border_width":{"unit":"px","top":"0","right":"0","bottom":"5","left":"0","isLinked":false},"_border_radius":{"unit":"px","top":"15","right":"15","bottom":"15","left":"15","isLinked":true},"_box_shadow_box_shadow_type":"yes","_box_shadow_box_shadow":{"horizontal":0,"vertical":10,"blur":30,"spread":0,"color":"rgba(0, 0, 0, 0.1)"},"_box_shadow_hover_box_shadow_type":"yes","_box_shadow_hover_box_shadow":{"horizontal":0,"vertical":20,"blur":40,"spread":0,"color":"rgba(0, 0, 0, 0.15)"},"__globals__":{"_border_color":"globals/colors?id=96221b7","title_color":"globals/colors?id=156ff82","hover_title_color":"globals/colors?id=156ff82","description_color":"globals/colors?id=e6db5d2"},"title_color":"#8DC63F","element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out","_border_color":"#D3DB26","description_color":"#28324B"},"elements":[],"widgetType":"image-box"}],"isInner":true}],"isInner":false},{"id":"9939934","elType":"container","settings":{"flex_direction":"column","flex_gap":{"column":"40","row":"40","isLinked":true,"unit":"px","size":40},"background_background":"classic","padding":{"unit":"px","top":"60","right":"20","bottom":"60","left":"20","isLinked":false},"__globals__":{"background_color":""},"element_pack_agbg_color_list":[{"_id":"ab15429"},{"start_color":"#567445","end_color":"#1D1BE0","_id":"ac6e3e6"}]},"elements":[{"id":"50ca588","elType":"widget","settings":{"html":"    <style>

        .main-container {
            font-family: 'Poppins', sans-serif;
            
            border-radius: 8px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.1);
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, 0.2);
        }

       .main-container .header {
            background: linear-gradient(284deg, #03A69A 0%, #D3DB26 100%);
            padding: 30px 40px;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

       .main-container .header::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
            /*animation: rotate 20s linear infinite;*/
        }

        .main-container .header h2 {
            color: white;
            font-size: 2.5rem;
            font-weight: 700;
            margin-bottom: 10px;
            position: relative;
            z-index: 2;
        }

       .main-container .header p {
            color: rgb(40, 50, 75);
            font-size: 1.1rem;
            position: relative;
            z-index: 2;
        }

        .table-container {
            overflow-x: auto;
            /*max-height: 70vh;*/
            position: relative;
        }

        .modern-table {
            width: 100%;
            text-align: center;
            /* border-collapse: collapse; */
            /*background: white;*/
        }

        .modern-table thead {
            /*background: linear-gradient(135deg, #1a202c 0%, #2d3748 100%);*/
            position: sticky;
            top: 0;
            z-index: 10;
        }

        .modern-table th {
            padding: 20px 16px;
            text-align: center;
            font-weight: 600;
            font-size: 0.9rem;
            color: #00a79d;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            position: relative;
            /* background: linear-gradient(135deg, rgba(102, 126, 234, 0.05) 0%, rgba(118, 75, 162, 0.05) 100%); */
        }

        .modern-table th::after {
            content: '';
            position: absolute;
            bottom: -3px;
            left: 0;
            width: 0;
            height: 3px;
            /* background: #48bb78; */
            transition: width 0.3s ease;
        }

        .modern-table th:hover::after {
            width: 100%;
        }

        .modern-table tbody tr {
            transition: all 0.3s ease;
        }
        .modern-table tbody tr:not(:last-child) {
            border-bottom: 1px solid rgba(226, 232, 240, 0.5);
        }
        
   .modern-table table {
  border: 1px solid rgb(0, 167, 157, 0.4);
}

        .modern-table tbody tr:hover {
            background: linear-gradient(135deg, rgba(102, 126, 234, 0.05) 0%, rgba(118, 75, 162, 0.05) 100%);
        }

        .modern-table td:nth-child(2), .modern-table td:nth-child(3), .modern-table td:nth-child(4), .modern-table td:nth-child(5) {
            color: rgb(40, 50, 75);
        }

        .modern-table td {
            padding: 20px 16px;
            font-size: 0.95rem;
            line-height: 1.5;
            vertical-align: center;
            position: relative;
        }

        .plant-type {
            font-weight: 700;
            color: #00a79d;
            font-size: 1rem;
        }

        .rate-value {
            font-weight: 600;
            color: #4a5568;
            font-family: 'Monaco', 'Menlo', monospace;
        }

        .directions {
            color: #3b362f;
            font-style: italic;
            max-width: 250px;
        }

        .badge {
            display: inline-block;
            padding: 4px 12px;
            background: linear-gradient(135deg, #667eea, #764ba2);
            color: white;
            border-radius: 20px;
            font-size: 0.8rem;
            font-weight: 500;
            margin: 2px;
        }

        .mobile-card {
            display: none;
        }

        @media (max-width: 768px) {

            .header h1 {
                font-size: 1.8rem;
            }

            .modern-table,
            .table-container {
                display: none;
            }

            .mobile-card {
                display: block;
                padding: 12px;
            }

            .card {
                background: white;
                border-radius: 16px;
                padding: 20px;
                margin-bottom: 16px;
                box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
                border-bottom: 4px solid #619186;
                transition: all 0.3s ease;
            }

            .card:hover {
                transform: translateY(-4px);
                box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15);
            }

            .card-title {
                font-weight: 700;
                color: #3b362f;
                margin-bottom: 12px;
                font-size: 1.1rem;
            }

            .card-row {
                display: flex;
                justify-content: space-between;
                align-items: flex-start;
                margin-bottom: 8px;
                padding: 4px 0;
                border-bottom: 1px solid rgba(226, 232, 240, 0.3);
            }

            .card-row:last-child {
                border-bottom: none;
                margin-bottom: 0;
            }

            .card-label {
                font-weight: 600;
                color: #4a5568;
                font-size: 0.85rem;
                flex: 0 0 auto;
                margin-right: 10px;
            }

            .card-value {
                color: #718096;
                font-size: 0.9rem;
                text-align: right;
                flex: 1;
            }

            .card-directions {
                /* margin-top: 12px; */
                padding: 12px;
                background: rgba(102, 126, 234, 0.05);
                border-radius: 8px;
                /* font-style: italic; */
                color: #718096;
                font-size: 0.9rem;
                line-height: 1.4;
            }
        }

       

        
    </style>

    <div class="container main-container">
        <div class="header">
            <h2><img src="https://www.vertui.com/wp-content/uploads/2025/08/leaves-of-a-plant.png" style="width:40px;" /> Stage-by-Stage Application Guide</h1>
            <p>Professional application instructions for optimal plant care throughout growth stages</p>
        </div>

        <div class="table-container" id="tableContainer">
            <table class="modern-table" id="plantTable">
                <thead>
                    <tr>
                        <th>Stage</th>
                        <th>Root Ignite Bio</th>
                        <th>Crop Aid Myco Spora 10X</th>
                        <th>Hydro Balance Pro</th>
                        <th>Canopy Care Elite</th>
                        <th>Vigor Spray Max</th>
                        <th>Soil Vitality Max</th>
                    </tr>
                </thead>
                <tbody id="tableBody">
                    <tr>
                        <td class="plant-type">Pre-Season / Soil Prep</td>
                        <td class="rate-value">—</td>
                        <td class="rate-value">—</td>
                        <td class="directions">Adjust irrigation water pH before first feeding.</td>
                        <td class="rate-value">—</td>
                        <td class="rate-value">—</td>
                        <td class="directions">Apply to soil to replenish organic matter & beneficial microbes.</td>
                    </tr>
                    <tr>
                        <td class="plant-type">Seeding / Planting</td>
                        <td class="directions">In-furrow or soil drench (25-30 ml per 1 L water).</td>
                        <td class="directions"><strong>Mix with water, apply as a drench (1 g per 2,392 sq yd / 2,000 m²). Never dry.</strong></td>
                        <td class="directions">Adjust pH before mixing nutrients.</td>
                        <td class="rate-value">—</td>
                        <td class="directions">Optional foliar mist for vigor.</td>
                        <td class="directions">Broadcast to the planting area to boost microbial life.</td>
                    </tr>
                    <tr>
                        <td class="plant-type">Transplanting</td>
                        <td class="directions">Root-zone drench (17 ml per 1 L water).</td>
                        <td class="directions"><strong>Mix in 4 L of water; root dip or drench into the planting hole (1 g per 4 L). Never let it dry.</strong></td>
                        <td class="directions">Adjust pH before transplant nutrients.</td>
                        <td class="directions">Foliar feed if stress is visible.</td>
                        <td class="directions">Foliar or drench to aid establishment.</td>
                        <td class="directions">Drench the planting hole or soil to build a microbial base.</td>
                    </tr>
                    <tr>
                        <td class="plant-type">Early Growth (Weeks 3–4)</td>
                        <td class="directions">Reapply every 3-4 weeks during establishment or after stress.</td>
                        <td class="rate-value">—</td>
                        <td class="directions">Maintain irrigation pH.</td>
                        <td class="directions">Foliar spray to prevent deficiencies.</td>
                        <td class="directions">Foliar or soil feed to boost growth.</td>
                        <td class="directions">Light drench to feed soil microbes and release nutrients.</td>
                    </tr>
                    <tr>
                        <td class="plant-type">Vegetative Growth</td>
                        <td class="directions">— (unless stressed)</td>
                        <td class="rate-value">—</td>
                        <td class="directions">Maintain pH in irrigation/fertigation.</td>
                        <td class="directions">Foliar correction of deficiencies.</td>
                        <td class="directions">Apply every 3-4 weeks for vigor.</td>
                        <td class="directions">Mid-season drench to refresh soil biology.</td>
                    </tr>
                    <tr>
                        <td class="plant-type">Mid-Season Maintenance</td>
                        <td class="rate-value">—</td>
                        <td class="rate-value">—</td>
                        <td class="directions">Ongoing pH optimization.</td>
                        <td class="directions">Foliar spray every 3-4 weeks.</td>
                        <td class="directions">Broadcast foliar spray for vigor.</td>
                        <td class="directions">Broadcast or drench to restore soil vitality.</td>
                    </tr>
                    <tr>
                        <td class="plant-type">Stress Recovery</td>
                        <td class="directions">Drench after drought, damage, or root stress.</td>
                        <td class="directions">Reapply only if severe stress or soil disturbance occurs.</td>
                        <td class="directions">Adjust pH to ensure recovery nutrients are available.</td>
                        <td class="directions">Foliar spray for rapid correction.</td>
                        <td class="directions">Foliar + drench for recovery.</td>
                        <td class="directions">Apply to rebalance soil microbes.</td>
                    </tr>
                    <tr>
                        <td class="plant-type">Turf & Lawns</td>
                        <td class="directions">Apply at seeding or after aeration.</td>
                        <td class="directions"><strong>Mix with water at seeding or sod install (never dry).</strong></td>
                        <td class="directions">Adjust pH before adding fertilizers.</td>
                        <td class="directions">Foliar spray for yellowing or poor growth.</td>
                        <td class="directions">Broadcast spray for density & vigor.</td>
                        <td class="directions">Broadcast soil application early season & mid-summer.</td>
                    </tr>
                </tbody>
            </table>
        </div>

        <div class="mobile-card" id="mobileContainer">
            <div class="card">
                <div class="card-title">Pre-Season / Soil Prep</div>
                <div class="card-row">
                    <span class="card-label">Root Ignite Bio:</span>
                    <span class="card-value">—</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Crop Aid Myco Spora 10X:</span>
                    <span class="card-value">—</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Hydro Balance Pro:</span>
                    <span class="card-value">Adjust irrigation water pH before first feeding.</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Canopy Care Elite:</span>
                    <span class="card-value">—</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Vigor Spray Max:</span>
                    <span class="card-value">—</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Soil Vitality Max:</span>
                    <span class="card-value">Apply to soil to replenish organic matter & beneficial microbes.</span>
                </div>
            </div>
            <div class="card">
                <div class="card-title">Seeding / Planting</div>
                <div class="card-row">
                    <span class="card-label">Root Ignite Bio:</span>
                    <span class="card-value">In-furrow or soil drench (25-30 ml per 1 L water).</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Crop Aid Myco Spora 10X:</span>
                    <span class="card-value">Mix with water, apply as a drench (1 g per 2,392 sq yd / 2,000 m²). Never dry.</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Hydro Balance Pro:</span>
                    <span class="card-value">Adjust pH before mixing nutrients.</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Canopy Care Elite:</span>
                    <span class="card-value">—</span>
