"},"elements":[],"widgetType":"toggle"},{"id":"4701383","elType":"widget","settings":{"tabs":[{"tab_title":"How are Vertui products connected to Crop Aid Nutrition?","tab_content":"<p><span style="font-weight: 400;">Vertui is the </span><b>horticultural branch of Crop Aid Nutrition</b><span style="font-weight: 400;">, a Saskatchewan-based leader in agricultural biostimulants and fertilizers. Crop Aid’s 20+ years of experience in </span><b>soil science and farmer-focused innovation</b><span style="font-weight: 400;"> directly shape Vertui’s horticultural solutions.</span></p>","_id":"24d7857"},{"tab_title":"Where can I purchase Vertui products?","tab_content":"<p><span style="font-weight: 400;">Vertui products are available through our </span><b>authorized distributors</b><span style="font-weight: 400;"> across Canada and the U.S. For direct inquiries, please contact us to be connected with a representative in your area.</span></p>","_id":"8ea63a1"},{"tab_title":"Do you provide technical support?","tab_content":"<p><span style="font-weight: 400;">Absolutely. Our specialists are here to help with product recommendations, application guidance, and troubleshooting. We pride ourselves on </span><b>partnership and customer service throughout the growing season.</b></p>","_id":"e2f16a9"},{"tab_title":"Can Vertui products be integrated with other fertilizers or inputs?","tab_content":"<p><span style="font-weight: 400;">Yes. Our formulations are designed to be </span><b>flexible and compatible</b><span style="font-weight: 400;">, but we recommend consulting our team for best practices to maximize results and avoid interactions with certain inputs.</span></p>","_id":"a5a313f"},{"tab_title":"How soon will I see results from using Vertui?","tab_content":"<p><span style="font-weight: 400;">Many growers notice improved </span><b>germination, vigor, and plant resilience</b><span style="font-weight: 400;"> within the first growth cycle. Long-term benefits include </span><b>stronger root systems, healthier soil ecosystems, and improved yield and quality.</b></p>","_id":"34212e9"}],"faq_schema":"yes","border_width":{"unit":"px","size":0,"sizes":[]},"border_color":"#33415521","title_color":"#8DC63F","tab_active_color":"#00A79D","title_typography_typography":"custom","title_typography_font_family":"Poppins","title_typography_font_size":{"unit":"px","size":18,"sizes":[]},"title_typography_font_weight":"600","icon_color":"#8DC63F","icon_active_color":"#00A79D","icon_space":{"unit":"px","size":6,"sizes":[]},"content_color":"#7A7A7A","_box_shadow_box_shadow":{"horizontal":0,"vertical":10,"blur":30,"spread":0,"color":"rgba(0, 0, 0, 0.1)"},"__globals__":{"title_color":"globals/colors?id=96221b7","tab_active_color":"globals/colors?id=96221b7","icon_color":"globals/colors?id=7f0ba7e","icon_active_color":"globals/colors?id=7f0ba7e","content_color":"globals/colors?id=7f0ba7e","border_color":""},"selected_icon":{"value":"fas fa-plus","library":"fa-solid"},"content_padding":{"unit":"px","top":"0","right":"20","bottom":"0","left":"20","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out","_box_shadow_hover_box_shadow":{"horizontal":0,"vertical":20,"blur":40,"spread":0,"color":"rgba(0, 0, 0, 0.15)"},"selected_active_icon":{"value":"fas fa-lightbulb","library":"fa-solid"},"icon_align":"right","custom_css":"selector .elementor-toggle-item {
