    <style>

        .main-container {
            font-family: 'Poppins', sans-serif;
            
            border-radius: 8px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.1);
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, 0.2);
        }

       .main-container .header {
            background: linear-gradient(135deg, #3b362f 0%, #619186 100%);
            padding: 30px 40px;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

       .main-container .header::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
            /*animation: rotate 20s linear infinite;*/
        }

        .main-container .header h1 {
            color: white;
            font-size: 2.5rem;
            font-weight: 700;
            margin-bottom: 10px;
            position: relative;
            z-index: 2;
        }

       .main-container .header p {
            color: rgba(255, 255, 255, 0.8);
            font-size: 1.1rem;
            position: relative;
            z-index: 2;
        }

        .table-container {
            overflow-x: auto;
            /*max-height: 70vh;*/
            position: relative;
        }

        .modern-table {
            width: 100%;
            text-align: center;
            /* border-collapse: collapse; */
            /*background: white;*/
        }

        .modern-table thead {
            /*background: linear-gradient(135deg, #1a202c 0%, #2d3748 100%);*/
            position: sticky;
            top: 0;
            z-index: 10;
        }

        .modern-table th {
            padding: 20px 16px;
            text-align: center;
            font-weight: 600;
            font-size: 0.9rem;
            color: #619186;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            position: relative;
            /* background: linear-gradient(135deg, rgba(102, 126, 234, 0.05) 0%, rgba(118, 75, 162, 0.05) 100%); */
        }

        .modern-table th::after {
            content: '';
            position: absolute;
            bottom: -3px;
            left: 0;
            width: 0;
            height: 3px;
            /* background: #48bb78; */
            transition: width 0.3s ease;
        }

        .modern-table th:hover::after {
            width: 100%;
        }

        .modern-table tbody tr {
            transition: all 0.3s ease;
        }
        .modern-table tbody tr:not(:last-child) {
            border-bottom: 1px solid rgba(226, 232, 240, 0.5);
        }

        .modern-table tbody tr:hover {
            background: linear-gradient(135deg, rgba(102, 126, 234, 0.05) 0%, rgba(118, 75, 162, 0.05) 100%);
        }

        .modern-table td:nth-child(2), .modern-table td:nth-child(3), .modern-table td:nth-child(4), .modern-table td:nth-child(5) {
            color: #619186;
        }

        .modern-table td {
            padding: 20px 16px;
            font-size: 0.95rem;
            line-height: 1.5;
            vertical-align: center;
            position: relative;
        }

        .plant-type {
            font-weight: 700;
            color: #3b362f;
            font-size: 1rem;
        }

        .rate-value {
            font-weight: 600;
            color: #4a5568;
            font-family: 'Monaco', 'Menlo', monospace;
        }

        .directions {
            color: #3b362f;
            font-style: italic;
            max-width: 250px;
        }

        .badge {
            display: inline-block;
            padding: 4px 12px;
            background: linear-gradient(135deg, #667eea, #764ba2);
            color: white;
            border-radius: 20px;
            font-size: 0.8rem;
            font-weight: 500;
            margin: 2px;
        }

        .mobile-card {
            display: none;
        }

        @media (max-width: 768px) {

            .header h1 {
                font-size: 1.8rem;
            }

            .modern-table,
            .table-container {
                display: none;
            }

            .mobile-card {
                display: block;
                padding: 12px;
            }

            .card {
                background: white;
                border-radius: 16px;
                padding: 20px;
                margin-bottom: 16px;
                box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
                border-bottom: 4px solid #619186;
                transition: all 0.3s ease;
            }

            .card:hover {
                transform: translateY(-4px);
                box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15);
            }

            .card-title {
                font-weight: 700;
                color: #3b362f;
                margin-bottom: 12px;
                font-size: 1.1rem;
            }

            .card-row {
                display: flex;
                justify-content: space-between;
                align-items: center;
                margin-bottom: 8px;
                padding: 4px 0;
                border-bottom: 1px solid rgba(226, 232, 240, 0.3);
            }

            .card-row:last-child {
                border-bottom: none;
                margin-bottom: 0;
