ow soon can I expect to see results?","tab_content":"<p>Benefits begin below the soil surface immediately after colonization. Visible improvements in growth, vigour, and resilience are often noticeable within 3–6 weeks under good growing conditions.</p>","_id":"a7a74ea"},{"tab_title":"Is Crop Aid Myco Spora 10X safe for edible plants and pets?","tab_content":"<p>Yes, it can be used on edible plants and is safe for areas where pets are present when applied as directed.</p>","_id":"57fc4b8"}],"selected_icon":{"value":"fas fa-plus","library":"fa-solid"},"faq_schema":"yes","border_width":{"unit":"px","size":0,"sizes":[]},"border_color":"#33415521","title_color":"#8DC63F","tab_active_color":"#00A79D","title_typography_typography":"custom","title_typography_font_family":"Poppins","title_typography_font_size":{"unit":"px","size":18,"sizes":[]},"title_typography_font_weight":"600","icon_color":"#8DC63F","icon_active_color":"#00A79D","content_color":"#7A7A7A","_box_shadow_box_shadow":{"horizontal":0,"vertical":10,"blur":30,"spread":0,"color":"rgba(0, 0, 0, 0.1)"},"_box_shadow_hover_box_shadow":{"horizontal":0,"vertical":20,"blur":40,"spread":0,"color":"rgba(0, 0, 0, 0.15)"},"__globals__":{"title_color":"globals/colors?id=987f53f","tab_active_color":"globals/colors?id=987f53f","icon_color":"globals/colors?id=e867a9b","icon_active_color":"globals/colors?id=e867a9b","content_color":"globals/colors?id=e867a9b","border_color":""},"content_padding":{"unit":"px","top":"0","right":"20","bottom":"0","left":"20","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out","selected_active_icon":{"value":"fas fa-lightbulb","library":"fa-solid"},"title_padding":{"unit":"px","top":"20","right":"14","bottom":"20","left":"14","isLinked":false},"icon_align":"right","custom_css":"selector .elementor-toggle-item {
