a:2:{s:10:"custom_css";s:2279:"table {
            width: 100%;
            /*border-collapse: collapse;*/
            /*border: 1px solid #98B63C;*/
        }
        
        th:nth-child(1), td:nth-child(1) {
            width: 25%;
            min-width: calc(140px, auto);
        }

        th {
            background: #f1f5f9;
            color: rgb(3,166,154);
            font-weight: 600;
            padding: 1rem;
            text-align: left;
            border-bottom: 2px solid #e2e8f0;
            text-align: center;
        }

        /*th:last-child {*/
        /*    text-align: center;*/
        /*}*/

        tbody tr {
            border-bottom: 1px solid #f1f5f9;
            transition: background-color 0.2s ease;
        }

        tbody tr:hover {
            background: #f8fafc;
        }

        tbody tr:last-child {
            border-bottom: none;
        }

        td {
            padding: 0.875rem 1rem;
            color: #29334b;
            vertical-align: center;
            text-align: center;
        }

        .nutrient-name {
            font-weight: 500;
            /*color: #03a69a;*/
        }

        .chemical-formula {
            font-size: 0.875rem;
            color: #c;
            margin-top: 2px;
        }

        .percentage {
            font-weight: 600;
            color: #03a69a;
            font-size: 1rem;
        }

        .description {
