s":[{"id":"af1a6a0","elType":"widget","settings":{"tabs":[{"tab_title":"What is Vertui?","tab_content":"<p><span style="font-weight: 400;">Vertui is a horticultural solutions brand built on the proven science of </span><b>Crop Aid Nutrition</b><span style="font-weight: 400;">, a Canadian company with over 20 years of expertise in soil and plant health. Our mission is to bring advanced, sustainable agricultural innovations into the horticulture space.</span></p>","_id":"24d7857"},{"tab_title":"How is Vertui different from other horticultural products?","tab_content":"<p><span style="font-weight: 400;">Our products are </span><b>science-driven and sustainability-focused</b><span style="font-weight: 400;">. Unlike generic fertilizers, Vertui solutions use:</span></p><ul><li><b>Carbon-based biostimulants</b><span style="font-weight: 400;"> to support beneficial soil microbes</span></li><li><b>Nutrient-packed seed primers</b><span style="font-weight: 400;"> to improve germination and vigor</span></li><li><b>Chelated micronutrients</b><span style="font-weight: 400;"> for superior plant uptake</span></li><li><b>Plant-based extracts and peptides</b><span style="font-weight: 400;"> to reduce impurities and environmental impact</span></li></ul>","_id":"8ea63a1"},{"tab_title":"Are Vertui products safe and compliant?","tab_content":"<p><span style="font-weight: 400;">Yes. All Vertui formulations are manufactured to meet or exceed </span><b>Canadian and U.S. compliance regulations</b><span style="font-weight: 400;">, with transparency and traceability at every step. Our facilities follow strict quality standards, ensuring both safety and effectiveness.</span></p>","_id":"a7a74ea"},{"tab_title":"Who can benefit from Vertui products?","tab_content":"<p><span style="font-weight: 400;">Vertui is designed for </span><b>horticulture growers, greenhouse operators, nurseries, and indoor cultivation facilities</b><span style="font-weight: 400;">. Whether you’re focused on ornamentals, fruits, vegetables, or specialty crops, our solutions can improve plant health, resilience, and yield.</span></p>","_id":"57fc4b8"},{"tab_title":"How do Vertui products support sustainability?","tab_content":"<p><span style="font-weight: 400;">We prioritize eco-conscious practices by using </span><b>plant-based ingredients</b><span style="font-weight: 400;">, minimizing chemical impurities, and formulating products that </span><b>support long-term soil and plant health</b><span style="font-weight: 400;">. This means healthier crops today and a stronger environment tomorrow.</span></p>","_id":"60e5cf6"}],"selected_icon":{"value":"fas fa-plus","library":"fa-solid"},"faq_schema":"yes","border_width":{"unit":"px","size":0,"sizes":[]},"border_color":"#33415521","title_color":"#8DC63F","tab_active_color":"#00A79D","title_typography_typography":"custom","title_typography_font_family":"Poppins","title_typography_font_size":{"unit":"px","size":18,"sizes":[]},"title_typography_font_weight":"600","icon_color":"#8DC63F","icon_active_color":"#00A79D","icon_space":{"unit":"px","size":6,"sizes":[]},"content_color":"#7A7A7A","_box_shadow_box_shadow":{"horizontal":0,"vertical":10,"blur":30,"spread":0,"color":"rgba(0, 0, 0, 0.1)"},"_box_shadow_hover_box_shadow":{"horizontal":0,"vertical":20,"blur":40,"spread":0,"color":"rgba(0, 0, 0, 0.15)"},"__globals__":{"title_color":"globals/colors?id=96221b7","tab_active_color":"globals/colors?id=96221b7","icon_color":"globals/colors?id=7f0ba7e","icon_active_color":"globals/colors?id=7f0ba7e","content_color":"globals/colors?id=7f0ba7e","border_color":""},"content_padding":{"unit":"px","top":"0","right":"20","bottom":"0","left":"20","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out","selected_active_icon":{"value":"fas fa-lightbulb","library":"fa-solid"},"icon_align":"right","custom_css":"selector .elementor-toggle-item {
    box-shadow: 0px 10px 30px rgba(0, 0, 0, 0.1);
}

