                </div>
                <div class="card-row">
                    <span class="card-label">Rate (100 m²):</span>
                    <span class="card-value">0.015 - 0.017 oz</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Water Volume:</span>
                    <span class="card-value">4 L (1.06 gal)</span>
                </div>
                <div class="card-directions">Apply 10 mL (0.34 US fl oz) of the suspension to the roots before planting the hole.</div>
            </div>
            <div class="card">
                <div class="card-title">Established Berries</div>
                <div class="card-row">
                    <span class="card-label">Rate (1,000 sq ft):</span>
                    <span class="card-value">0.040 - 0.052 g</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Rate (100 m²):</span>
                    <span class="card-value">0.015 - 0.020 oz</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Water Volume:</span>
                    <span class="card-value">4-6 L (1.06-1.59 gal)</span>
                </div>
                <div class="card-directions">Apply via irrigation during the growing season.</div>
            </div>
            <div class="card">
                <div class="card-title">Established Grapes, Apples, Other Fruits</div>
                <div class="card-row">
                    <span class="card-label">Rate (1,000 sq ft):</span>
                    <span class="card-value">0.045 - 0.058 g</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Rate (100 m²):</span>
                    <span class="card-value">0.017 - 0.022 oz</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Water Volume:</span>
                    <span class="card-value">6-8 L (1.59–2.11 gal)</span>
                </div>
                <div class="card-directions">Apply via irrigation during the growing season.</div>
            </div>
            <div class="card">
                <div class="card-title">Established Ornamentals & Shrubs</div>
                <div class="card-row">
                    <span class="card-label">Rate (1,000 sq ft):</span>
                    <span class="card-value">0.045 - 0.052 g</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Rate (100 m²):</span>
                    <span class="card-value">0.017 - 0.020 oz</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Water Volume:</span>
                    <span class="card-value">4-6 L (1.06-1.59 gal)</span>
                </div>
                <div class="card-directions">Apply via irrigation during the growing season.</div>
            </div>
            <div class="card">
                <div class="card-title">Established Turf & Lawns</div>
                <div class="card-row">
                    <span class="card-label">Rate (1,000 sq ft):</span>
                    <span class="card-value">0.058 - 0.069 g</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Rate (100 m²):</span>
                    <span class="card-value">0.022 - 0.026 oz</span>
                </div>
                <div class="card-row">
                    <span class="card-label">Water Volume:</span>
                    <span class="card-value">10-15 L (2.64-3.96 gal)</span>
                </div>
                <div class="card-directions">Apply via irrigation during the growing season.</div>
            </div>
        </div>
    </div>
