<thead>
<tr>
<th>Nutrient Component</th>
<th>Percentage</th>
<th>Description</th>
</tr>
</thead>
<tbody>
<tr>
<td>
<div><b>Total Nitrogen</b></div>
<div>(N)</div></td>
<td class="percentage">7%</td>
<td><span style="font-weight: 400;">Promotes lush, green growth by fueling leaf development and overall plant vigor.</span></td>
</tr>
<tr>
<td>
<div><b>Phosphoric Acid</b></div>
<div>(P₂O₅)</div></td>
<td class="percentage">13%</td>
<td><span style="font-weight: 400;"> Enhances root health, energy transfer, and the development of strong flowering and fruiting structures.</span></td>
</tr>
<tr>
<td>
<div><b>Sulphur</b></div>
<div>(S)</div></td>
<td class="percentage">5%</td>
<td><span style="font-weight: 400;"> Supports protein formation, improves leaf colour, and aids in chlorophyll production for healthy foliage.</span></td>
</tr>
<tr>
<td>
<div><b>Iron (Fe)</b></div>
<div><b> </b>(EDTA)</div></td>
<td class="percentage"><b>0.17%</b><b>
</b></td>
<td><span style="font-weight: 400;">Prevents yellowing by supporting chlorophyll synthesis, helping leaves stay vibrant and green.</span></td>
</tr>
<tr>
<td>
<div><b>Manganese</b></div>
<div>(Mn) (EDTA)</div></td>
<td class="percentage">0.05%</td>
<td><span style="font-weight: 400;">It aids photosynthesis, enzyme activation, and the breakdown of carbohydrates for plant energy.</span></td>
</tr>
<tr>
<td>
<div><b>Zinc</b></div>
<div>(Zn-EDTA)</div></td>
<td class="percentage"><b>0.09%</b></td>
<td><span style="font-weight: 400;"> Supports the production of growth hormones and enzymes needed for leaf expansion and development.</span></td>
</tr>
<tr>
<td>
<div><b>Copper</b></div>
<div>(Cu) (EDTA)</div></td>
<td class="percentage">0.05%</td>
<td><span style="font-weight: 400;">Strengthens cell walls, aids reproductive growth, and helps plants defend against disease.</span></td>
</tr>
<tr>
<td>
<div><b>Molybdenum</b></div>
<div>(Mo) (EDTA)</div>
<div></div></td>
<td class="percentage">0.07%</td>
<td><span style="font-weight: 400;">Improves nitrogen use efficiency, aiding in the conversion of nitrogen into plant proteins.</span></td>
</tr>
<tr>
<td>
<div><b>Boron</b></div>
<div>(B)</div></td>
<td class="percentage">0.016%</td>
<td><span style="font-weight: 400;">Supports flowering, pollen development, and the movement of sugars and nutrients within the plant.</span></td>
</tr>
</tbody>
</table>","_margin":{"unit":"px","top":"20","right":"0","bottom":"-24","left":"0","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out"},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"7bc886a","elType":"container","settings":{"flex_direction":"column","flex_gap":{"column":"40","row":"40","isLinked":true,"unit":"px","size":40},"padding":{"unit":"px","top":"60","right":"20","bottom":"60","left":"20","isLinked":false},"__globals__":{"background_color":""},"background_color":"#F1F4B217","element_pack_agbg_color_list":[{"_id":"ed56016"},{"start_color":"#567445","end_color":"#1D1BE0","_id":"fd8b194"}],"_element_id":"coverage"},"elements":[{"id":"350ee9f","elType":"widget","settings":{"title":"Coverage","align":"center","typography_typography":"custom","typography_font_family":"Poppins","typography_font_size":{"unit":"px","size":32,"sizes":[]},"typography_font_weight":"700","_element_custom_width":{"unit":"%","size":60,"sizes":[]},"_background_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_color_b_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_gradient_angle_tablet":{"unit":"deg","size":"","sizes":[]},"_background_gradient_angle_mobile":{"unit":"deg","size":"","sizes":[]},"_background_hover_color_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_hover_color_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_hover_color_b_stop_tablet":{"unit":"%","size":"","sizes":[]},"_background_hover_color_b_stop_mobile":{"unit":"%","size":"","sizes":[]},"_background_hover_gradient_angle_tablet":{"unit":"deg","size":"","sizes":[]},"_background_hover_gradient_angle_mobile":{"unit":"deg","size":"","sizes":[]},"__globals__":{"title_color":"globals/colors?id=b6a6